css:
.cd-hero{border:1px solid var(--cd-border);background:linear-gradient(#ffffff,#e4e4e4);border-radius:var(--cd-radius)}
.cd-hero-title{font-size:1.25em;font-weight:700;color:var(--cd-text)}
.cd-hero-cta{background:var(--cd-accent);color:var(--cd-accent-text);border:1px solid var(--cd-text);border-radius:var(--cd-radius)}
.cd-row-title{font-size:15px;font-weight:700;border-bottom:2px solid var(--cd-accent);padding-bottom:2px}
.cd-row-prev,.cd-row-next{background:linear-gradient(#ffffff,#dedede);border:1px solid var(--cd-border);color:var(--cd-text);border-radius:var(--cd-radius)}
.cd-card{border:1px solid var(--cd-border);background:var(--cd-surface);border-radius:var(--cd-radius)}
.cd-card-title{font-size:13px;font-weight:700;color:var(--cd-text)}
.cd-card-meta{font-size:11px;color:var(--cd-muted)}
.cd-card-duration{border-radius:var(--cd-radius);font-size:11px}
